{{ config(
            materialized='table',
                post_hook={
                    "sql": "Create Or Replace Table sleepycat_db.maplemonk.Sleepycat_db_marketing_sales_sessions_summary as (select UPPER( CASE WHEN REPLACE(LOWER(campaign_name), \' \', \'\') LIKE \'%petmat%\' THEN \'PET MAT\' WHEN REPLACE(LOWER(campaign_name), \' \', \'\') LIKE \'%petbed%\' THEN \'PETBED\' WHEN REPLACE(LOWER(campaign_name), \' \', \'\') LIKE \'%bedding%\' THEN \'BEDDING\' WHEN REPLACE(LOWER(campaign_name), \' \', \'\') LIKE \'%recliner%\' THEN \'RECLINER\' WHEN REPLACE(LOWER(campaign_name), \' \', \'\') LIKE \'%ergoverse%\' THEN \'ERGOVERSE\' WHEN REPLACE(LOWER(campaign_name), \' \', \'\') LIKE \'%cushion%\' THEN \'CUSHIONS\' WHEN REPLACE(LOWER(campaign_name), \' \', \'\') LIKE \'%pillow%\' THEN \'PILLOW\' WHEN REPLACE(LOWER(campaign_name), \' \', \'\') LIKE \'%mattresstopper%\' THEN \'MATTRESSES\' WHEN REPLACE(LOWER(campaign_name), \' \', \'\') LIKE \'%mattress%\' THEN \'MATTRESSES\' WHEN REPLACE(LOWER(campaign_name), \' \', \'\') LIKE \'%bed%\' THEN \'BED\' ELSE \'OTHERS\' END) AS category, case when lower(campaign_name) like \'%tofu%\' then \'TOFU (Top of funnel)\' when lower(campaign_name) like \'%mofu%\' then \'MOFU (Mid funnel)\' when lower(campaign_name) like \'%bofu%\' then \'BOFU (Bottom)\' else \'Others\' end as Campaign_Funnel, campaign_name, campaign_id, Date, Ad_type, ad_strength, ad_network_type, channel, clicks, spend, impressions, conversions, conversion_value, add_to_carts, add_to_cart_value, null order_id, null Quantity, null total_sales, null razor_status, null razor_error_bank, null state, null as city, null shopify_new_customer_flag, null Shopify_customer_id_final, null as discount, null as aov_bucket, null as item_count, null as LINE_ITEM_SALES, null as discount_code, null as discount_bucket from sleepycat_db.maplemonk.sleepycat_db_marketing_consolidated where lower(channel) like any (\'%google%\',\'%facebook%\') and not(lower(campaign_name) like \'%store%\') ) UNION ALL ( select category, null as Campaign_Funnel, null campaign_name, null campaign_id, order_timestamp::date Date, null as Ad_type, null ad_strength, null ad_network_type, null channel, null clicks, null spend, null impressions, null conversions, null conversion_value, null add_to_carts, null add_to_cart_value, order_id, Quantity, total_sales, razor_status, razor_error_bank, state, city, shopify_new_customer_flag, Shopify_customer_id_final, discount, aov_bucket, item_count, LINE_ITEM_SALES, discount_code, discount_bucket from sleepycat_db.maplemonk.sleepycat_db_shopify_fact_items f left join ( select order_id as aov_order_id, CASE WHEN SUM(IFNULL(total_sales,0)) < 5000 THEN \'₹<5K\' WHEN SUM(IFNULL(total_sales,0)) >= 5000 AND SUM(IFNULL(total_sales,0)) < 10000 THEN \'₹5-10K\' WHEN SUM(IFNULL(total_sales,0)) >= 10000 AND SUM(IFNULL(total_sales,0)) < 15000 THEN \'₹10-15K\' WHEN SUM(IFNULL(total_sales,0)) >= 15000 AND SUM(IFNULL(total_sales,0)) < 20000 THEN \'₹15-20K\' WHEN SUM(IFNULL(total_sales,0)) >= 20000 AND SUM(IFNULL(total_sales,0)) < 30000 THEN \'₹20-30K\' WHEN SUM(IFNULL(total_sales,0)) >= 30000 AND SUM(IFNULL(total_sales,0)) < 50000 THEN \'₹30-50K\' ELSE \'₹50K+\' END AS aov_bucket, CASE WHEN SUM(IFNULL(LINE_ITEM_SALES, 0) - IFNULL(TOTAL_SALES, 0)) < 1 THEN \'₹0 (no discount)\' WHEN SUM(IFNULL(LINE_ITEM_SALES, 0) - IFNULL(TOTAL_SALES, 0)) <= 500 THEN \'₹1 - ₹500\' WHEN SUM(IFNULL(LINE_ITEM_SALES, 0) - IFNULL(TOTAL_SALES, 0)) <= 1000 THEN \'₹501 - ₹1,000\' WHEN SUM(IFNULL(LINE_ITEM_SALES, 0) - IFNULL(TOTAL_SALES, 0)) <= 2000 THEN \'₹1,001 - ₹2,000\' WHEN SUM(IFNULL(LINE_ITEM_SALES, 0) - IFNULL(TOTAL_SALES, 0)) <= 5000 THEN \'₹2,001 - ₹5,000\' WHEN SUM(IFNULL(LINE_ITEM_SALES, 0) - IFNULL(TOTAL_SALES, 0)) <= 10000 THEN \'₹5,001 - ₹10,000\' ELSE \'₹10,000+\' END AS discount_bucket, count(distinct sku) as item_count from sleepycat_db.maplemonk.sleepycat_db_shopify_fact_items group by 1 ) aov_bucket on f.order_id = aov_bucket.aov_order_id );",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SLEEPYCAT_DB.information_schema.databases
            ),
            
            final as (
